update raffle_activity_account_month
set month_count_surplus=month_count_surplus + #{monthCountSurplus},
    month_count=month_count + #{monthCount}
where user_id = #{userId}
  and activity_id = #{activityId}
  and month = #{month}

update raffle_activity_account_month
set month_count_surplus=month_count_surplus - 1
where user_id = #{userId}
  and activity_id = #{activityId}
  and month = #{month}
  and month_count_surplus > 0

mapper.select:
select user_id,
       activity_id,
       month,
       month_count,
       month_count_surplus
from raffle_activity_account_month
where user_id = #{userId}
  and activity_id = #{activityId}
  and month = #{month}
